def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find connected components of nonzero, non-5 pattern cells.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or g[r][c] == 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        g[ny][nx] not in (0, 5) and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append(comp)

    # Find maximal straight runs of 5s and extend an adjacent pattern along them.
    for vertical in (True, False):
        visited = set()
        for r in range(h):
            for c in range(w):
                if g[r][c] != 5 or (r, c) in visited:
                    continue
                if vertical:
                    if r > 0 and g[r - 1][c] == 5:
                        continue
                    run = []
                    y = r
                    while y < h and g[y][c] == 5:
                        run.append((y, c))
                        visited.add((y, c))
                        y += 1
                    lo, hi = run[0][0], run[-1][0]
                else:
                    if c > 0 and g[r][c - 1] == 5:
                        continue
                    run = []
                    x = c
                    while x < w and g[r][x] == 5:
                        run.append((r, x))
                        visited.add((r, x))
                        x += 1
                    lo, hi = run[0][1], run[-1][1]

                run_set = set(run)
                for comp in comps:
                    # Associate a pattern component if it touches a side of the 5-run.
                    touches = False
                    for y, x in comp:
                        neighbors = ((y, x - 1), (y, x + 1)) if vertical else ((y - 1, x), (y + 1, x))
                        if any(p in run_set for p in neighbors):
                            touches = True
                            break
                    if not touches:
                        continue

                    r0 = min(y for y, x in comp)
                    r1 = max(y for y, x in comp)
                    c0 = min(x for y, x in comp)
                    c1 = max(x for y, x in comp)
                    if vertical:
                        for y in range(lo, hi + 1):
                            for x in range(c0, c1 + 1):
                                py = r0 + (y - r0) % (r1 - r0 + 1)
                                if g[py][x] not in (0, 5):
                                    g[y][x] = g[py][x]
                    else:
                        for x in range(lo, hi + 1):
                            for y in range(r0, r1 + 1):
                                px = c0 + (x - c0) % (c1 - c0 + 1)
                                if g[y][px] not in (0, 5):
                                    g[y][x] = g[y][px]
    return g
